<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/smart_city_v630.php';$u=sc630_require_user();$uid=(int)$u['id'];if(isset($_GET['read']))sc630_mark_notification((int)$_GET['read'],$uid);$rows=sc630_notifications($uid,100);sc630_public_header('Notification Center','Unified ShahkotPK account and city notifications.');
