<main><section class="sc630-subhero notifications"><div class="sc630-shell"><span>SMART NOTIFICATIONS</span><h1>All your city updates in one place.</h1><p>Orders, services, healthcare, wallet activity and city announcements can surface through this notification center.</p></div></section><div class="sc630-shell"><section class="sc630-panel sc630-notification-list"><?php if(!$rows):?><p class="empty">No notifications yet.</p><?php endif;?><?php foreach($rows as $n):?><article class="<?=$n['is_read']?'':'unread'?>"><i><?=e($n['icon']?:'◉')?></i><div><span><?=e(ucfirst($n['priority']))?></span><h3><?=e($n['title'])?></h3><p><?=e($n['message'])?></p><small><?=e(date('d M Y h:i A',strtotime($n['created_at'])))?></small><?php if($n['action_url']):?><a href="<?=e($n['action_url'])?>">Open →</a><?php endif;?></div><?php if(!$n['is_read']):?><a class="read" href="/notifications.php?read=<?=(int)$n['id']?>">Mark read</a><?php endif;?></article><?php endforeach;?></section></div></main><?php sc630_public_footer(); ?>
